CREATE TRIGGER file_record_fts_ad AFTER DELETE ON file_record BEGIN
    DELETE FROM file_record_fts WHERE rowid = old.id;
END

CREATE TRIGGER file_record_fts_au AFTER UPDATE ON file_record BEGIN
    DELETE FROM file_record_fts WHERE rowid = old.id;
    INSERT INTO file_record_fts(rowid, path, extension, hashes)
    VALUES (
        new.id,
        new.path,
        new.extension,
        trim(COALESCE(new.hash_md5, '') || ' ' || COALESCE(new.hash_sha1, '') || ' ' || COALESCE(new.hash_sha256, ''))
    );
END

CREATE TRIGGER artifact_fts_ad AFTER DELETE ON artifact BEGIN
    DELETE FROM artifact_fts WHERE rowid = old.id;
END

CREATE TRIGGER artifact_fts_au AFTER UPDATE ON artifact BEGIN
    DELETE FROM artifact_fts WHERE rowid = old.id;
    INSERT INTO artifact_fts(rowid, title, summary, metadata)
    VALUES (
        new.id,
        new.title,
        new.summary,
        new.data_json
    );
END

CREATE TRIGGER event_fts_ad AFTER DELETE ON event BEGIN
    DELETE FROM event_fts WHERE rowid = old.id;
END
